https://www.epur.io/", "investors": "Capitole Angels||C√©dric Delorme||MELIES Business Angels||Occitanie Angels", "sectors": "DeepTech||Robotics||Hardware", "siren": null, "source_name": "ft_funding_2019"}, {"org_name": "Internest", "slug": "internest", "city": "Paris", "stage": "pre_seed", "amount_eur": 0.28, "amount_original": 280000, "currency": "EUR", "announced_date": "2019-10-17", "website": "https://internest.fr", "investors": "Femmes Business Angels||Paris Business Angels||Val'Angels", "sectors": "SpaceTech & Aerospace||Hardware", "siren": "817879760", "source_name": "ft_funding_2019"}, {"org_name": "Blend my day", "slug": "blend-my-day", "city": "Paris", "stage": "pre_seed", "amount_eur": 0.15, "amount_original": 150000, "currency": "EUR", "announced_date": "2019-04-01", "website": "https://blendmyday.com/", "investors": null, "sectors": "FoodTech", "siren": null, "source_name": "ft_funding_2019"}, {"org_name": "HelioRec", "slug": "heliorec", "city": "Nantes", "stage": "pre_seed", "amount_eur": 0.0515, "amount_original": 51500, "currency": "EUR", "announced_date": "2019-05-27", "website": "https://heliorec.com/", "investors": null, "sectors": "CleanTech||Energy||Hardware", "siren": null, "source_name": "ft_funding_2019"}, {"org_name": "QuantsUnited", "slug": "quantsunited", "city": "Bidart", "stage": "pre_seed", "amount_eur": 0.05, "amount_original": 50000, "currency": "EUR", "announced_date": "2019-07-01", "website": "https://www.quantsunited.com", "investors": null, "sectors": "FinTech||SaaS||Artificial Intelligence", "siren": null, "source_name": "ft_funding_2019"}, {"org_name": "Livemotion.io", "slug": "livemotionio", "city": "Paris", "stage": "pre_seed", "amount_eur": 0.02, "amount_original": 20000, "currency": "EUR", "announced_date": "2019-02-28", "website": "https://www.livemotion.io/", "investors": "Nassim Cheaib", "sectors": "SaaS", "siren": null, "source_name": "ft_funding_2019"}]$j$) AS (org_name TEXT,slug TEXT,city TEXT,stage TEXT,amount_eur NUMERIC,amount_original NUMERIC,currency TEXT,announced_date TEXT,website TEXT,investors TEXT,sectors TEXT,siren TEXT,source_name TEXT);

-- Step A: create genuinely-new orgs (no slug match AND no existing SIREN)
INSERT INTO organizations (id,name,slug,organization_type,website,status,country,legacy_source,created_at,updated_at)
SELECT uuid_generate_v4(), d.org_name, d.slug, 'startup'::organization_type, NULLIF(d.website,''), 'active'::organization_status,'France','ft_funding_2000_2019',NOW(),NOW()
FROM (SELECT DISTINCT ON (slug) slug, org_name, website, siren FROM stg_hist ORDER BY slug, siren NULLS LAST) d
WHERE NOT EXISTS (SELECT 1 FROM organizations o WHERE o.slug=d.slug)
  AND NOT EXISTS (SELECT 1 FROM legal_entities le WHERE d.siren IS NOT NULL AND le.siren=d.siren)
ON CONFLICT (slug) DO NOTHING;

-- Step B: resolver slug -> org (prefer SIREN match; dedup against multi-row sirens)
DROP TABLE IF EXISTS _rhist;
CREATE TABLE _rhist AS
SELECT DISTINCT ON (d.slug) d.slug, COALESCE(le.organization_id, o.id) AS org_id
FROM (SELECT slug, (array_agg(siren) FILTER (WHERE siren IS NOT NULL))[1] AS siren FROM stg_hist GROUP BY slug) d
LEFT JOIN legal_entities le ON le.siren=d.siren
LEFT JOIN organizations o ON o.slug=d.slug
ORDER BY d.slug, (le.organization_id IS NOT NULL) DESC, le.organization_id, o.id;
CREATE UNIQUE INDEX _rhist_slug ON _rhist(slug);

-- Step C: cities + link (only where org has none)
INSERT INTO cities (id,name,slug,country,created_at,updated_at)
SELECT uuid_generate_v4(), c.city, lower(regexp_replace(regexp_replace(unaccent(c.city), '[^a-zA-Z0-9\s-]', '', 'g'), '\s+', '-', 'g')), 'France', NOW(),NOW()
FROM (SELECT DISTINCT city FROM stg_hist WHERE city IS NOT NULL AND city<>'') c
ON CONFLICT (slug) DO NOTHING;

UPDATE organizations o SET city_id=ci.id, updated_at=NOW()
FROM _rhist r
JOIN stg_hist s ON s.slug=r.slug
JOIN cities ci ON ci.slug=lower(regexp_replace(regexp_replace(unaccent(s.city), '[^a-zA-Z0-9\s-]', '', 'g'), '\s+', '-', 'g'))
WHERE o.id=r.org_id AND o.city_id IS NULL AND s.city IS NOT NULL AND s.city<>'';

-- Step D: funding rounds (dedup on org+date+stage, including pre-existing rows)
INSERT INTO funding_rounds (id, organization_id, stage, amount_eur, currency_original, amount_original, announced_date, is_estimated, is_verified, source_name, created_at)
SELECT DISTINCT ON (r.org_id, s.announced_date, s.stage)
       uuid_generate_v4(), r.org_id, s.stage::funding_stage, s.amount_eur, s.currency, s.amount_original, s.announced_date, FALSE, FALSE, s.source_name, NOW()
FROM stg_hist s JOIN _rhist r ON r.slug=s.slug
WHERE s.announced_date IS NOT NULL
  AND NOT EXISTS (SELECT 1 FROM funding_rounds fr WHERE fr.organization_id=r.org_id AND fr.announced_date=s.announced_date AND fr.stage=s.stage::funding_stage)
ORDER BY r.org_id, s.announced_date, s.stage, s.amount_eur DESC NULLS LAST;

-- Step E: investor links (match existing investor orgs by slug).
-- DISTINCT ON (round, investor) dedups within this batch (the same investor can
-- appear on the same deduped round via several staging rows); NOT EXISTS guards
-- against rows already present. Match rounds on (org, date, stage) only.
INSERT INTO funding_round_investors (id, funding_round_id, investor_id, is_lead, investor_name, created_at)
SELECT DISTINCT ON (fr.id, inv.id) uuid_generate_v4(), fr.id, inv.id, FALSE, iv.name, NOW()
FROM stg_hist s
JOIN _rhist r ON r.slug=s.slug
JOIN funding_rounds fr ON fr.organization_id=r.org_id AND fr.announced_date=s.announced_date AND fr.stage=s.stage::funding_stage
CROSS JOIN LATERAL unnest(string_to_array(s.investors,'||')) AS iv(name)
JOIN organizations inv ON inv.slug=lower(regexp_replace(regexp_replace(unaccent(iv.name), '[^a-zA-Z0-9\s-]', '', 'g'), '\s+', '-', 'g'))
WHERE iv.name<>'' AND NOT EXISTS (SELECT 1 FROM funding_round_investors x WHERE x.funding_round_id=fr.id AND x.investor_id=inv.id)
ORDER BY fr.id, inv.id;

-- Step F: sector links (match existing sectors by slug)
INSERT INTO organization_sectors (id, organization_id, sector_id, is_primary, created_at)
SELECT DISTINCT uuid_generate_v4(), r.org_id, sec.id, FALSE, NOW()
FROM stg_hist s
JOIN _rhist r ON r.slug=s.slug
CROSS JOIN LATERAL unnest(string_to_array(s.sectors,'||')) AS sc(name)
JOIN sectors sec ON sec.slug=lower(regexp_replace(regexp_replace(unaccent(sc.name), '[^a-zA-Z0-9\s-]', '', 'g'), '\s+', '-', 'g'))
WHERE sc.name<>''
ON CONFLICT (organization_id, sector_id) DO NOTHING;

-- Step G: promote first-listed sector to primary where org has none
UPDATE organization_sectors os SET is_primary=TRUE
FROM (
  SELECT DISTINCT ON (r.org_id) r.org_id, sec.id AS sector_id
  FROM stg_hist s JOIN _rhist r ON r.slug=s.slug
  CROSS JOIN LATERAL unnest(string_to_array(s.sectors,'||')) WITH ORDINALITY AS sc(name,ord)
  JOIN sectors sec ON sec.slug=lower(regexp_replace(regexp_replace(unaccent(sc.name), '[^a-zA-Z0-9\s-]', '', 'g'), '\s+', '-', 'g'))
  WHERE sc.name<>''
  ORDER BY r.org_id, sc.ord
) first
WHERE os.organization_id=first.org_id AND os.sector_id=first.sector_id
  AND NOT EXISTS (SELECT 1 FROM organization_sectors x WHERE x.organization_id=first.org_id AND x.is_primary=TRUE);

-- Step H: legal entities (SIRENs not already present anywhere)
INSERT INTO legal_entities (id, organization_id, legal_name, siren, country, is_primary, legacy_source, created_at, updated_at)
SELECT DISTINCT ON (s.siren) uuid_generate_v4(), r.org_id, upper(s.org_name), s.siren, 'France',
  NOT EXISTS (SELECT 1 FROM legal_entities le2 WHERE le2.organization_id=r.org_id), 'ft_funding_2000_2019', NOW(),NOW()
FROM stg_hist s JOIN _rhist r ON r.slug=s.slug
WHERE s.siren IS NOT NULL AND s.siren<>''
  AND NOT EXISTS (SELECT 1 FROM legal_entities le WHERE le.siren=s.siren)
ORDER BY s.siren;

-- Verification
SELECT 'Rounds (2000-2019)' AS entity, COUNT(*)::text FROM funding_rounds WHERE source_name IN ('dealroom_2000_2012','dealroom_2013_2015','dealroom_2016_2017','funding_2018','ft_funding_2019')
UNION ALL SELECT 'New orgs', COUNT(*)::text FROM organizations WHERE legacy_source='ft_funding_2000_2019'
UNION ALL SELECT 'Legal entities added', COUNT(*)::text FROM legal_entities WHERE legacy_source='ft_funding_2000_2019'
UNION ALL SELECT 'Investor links', COUNT(*)::text FROM funding_round_investors fri JOIN funding_rounds fr ON fr.id=fri.funding_round_id WHERE fr.source_name IN ('dealroom_2000_2012','dealroom_2013_2015','dealroom_2016_2017','funding_2018','ft_funding_2019');

DROP TABLE IF EXISTS _rhist;
DROP TABLE IF EXISTS stg_hist;

COMMIT;
